import Foundation

/// Strict all-file resource policy for the future native signer adapter, NOT the
/// SDK's omit/optional rules. Both legacy SHA1 and mandatory SHA256 are explicit.
/// Verification compares exact independently generated bytes, avoiding untrusted
/// plist duplicate-key/DTD/rule interpretation entirely. Not artifact authority.
struct NativeStrictCodeResources {
    struct Digests: Sendable {
        let sha1: Data
        let sha256: Data
    }
    static func encode(_ resources: [String: Digests]) throws -> Data {
        guard resources.count <= 10000 else { throw NativeSignedOutputError.unsupportedClaims }
        func escape(_ path: String) -> String {
            path.replacingOccurrences(of: "&", with: "&amp;")
                .replacingOccurrences(of: "<", with: "&lt;").replacingOccurrences(of: ">", with: "&gt;")
                .replacingOccurrences(of: "\"", with: "&quot;").replacingOccurrences(of: "'", with: "&apos;")
        }
        let keys = resources.keys.sorted()
        var legacy = ""; var modern = ""; var pathBytes = 0
        for path in keys {
            try Task.checkCancellation()
            guard !path.isEmpty, path.utf8.count <= 1024, path.utf8.allSatisfy({ $0 >= 32 && $0 < 127 }),
                  !path.hasPrefix("/"), !path.contains("\\"), !path.contains(":"), !path.contains("//"),
                  path.split(separator: "/", omittingEmptySubsequences: false).allSatisfy({ !$0.isEmpty && $0 != "." && $0 != ".." }),
                  let digest = resources[path], digest.sha1.count == 20, digest.sha256.count == 32 else { throw NativeSignedOutputError.unsupportedClaims }
            pathBytes += path.utf8.count
            guard pathBytes <= 256 * 1024 else { throw NativeSignedOutputError.unsupportedClaims }
            let key = "<key>" + escape(path) + "</key>"
            legacy += key + "<data>" + digest.sha1.base64EncodedString() + "</data>"
            modern += key + "<dict><key>hash2</key><data>" + digest.sha256.base64EncodedString() + "</data></dict>"
        }
        let xml = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<plist version=\"1.0\"><dict>"
            + "<key>files</key><dict>" + legacy + "</dict><key>files2</key><dict>" + modern + "</dict>"
            + "<key>rules</key><dict><key>^.*$</key><true/></dict>"
            + "<key>rules2</key><dict><key>^.*$</key><true/></dict></dict></plist>\n"
        let data = Data(xml.utf8)
        guard data.count <= 4 * 1024 * 1024 else { throw NativeSignedOutputError.unsupportedClaims }
        return data
    }
}
